        @server.mount_proc(path) { |req, res|
          begin
            increment_request_count
            log_rpc_request(path, kind)
            code, header, response = block.call(req, res)
          rescue => e
            remember_last_error(e)
            log_handler_failure(path, e)
            code = 500
            header = default_json_headers
            body = self.class.build_rpc_error_payload(e, e.backtrace)
            response = nil
