        register_interrupt_workers(owner)
        register_kill_workers(owner)
        register_flush_and_kill(owner)
        register_flush_buffers(owner)
        register_config_reload(owner)
        register_config_dump(owner)
        register_graceful_reload(owner)
        register_get_dump(owner) if enable_get_dump
        handler_count
